```js
function formatPrice(amount, { currency = "INR", decimals = 2 } = {}) {
  if (!Number.isFinite(amount)) {
    throw new TypeError("amount must be a finite number");
  }
  return new Intl.NumberFormat("en-IN", {
    style: "currency", currency, minimumFractionDigits: decimals,
  }).format(amount);
}

formatPrice(99);                       // "₹99.00"
formatPrice(99, { decimals: 0 });      // "₹99"

function sum(...nums) { return nums.reduce((t, n) => t + n, 0); }
sum(1, 2, 3);                          // 6
```

| Feature | Behaviour |
|---|---|
| `x = 5`. | used when x is undefined. |
| `...rest`. | array of remaining arguments. |
| `{ a = 1 } = {}`. | safe destructuring even with no argument. |
| throw on invalid input. | a clear failure contract. |

